import assert from \"node:assert/strict\";
import { rmSync } from \"node:fs\";
import { runMigrations } from \"./src/server/db/migrate\";
import { getDb, organizations, members, activityEvents, apiTokens } from \"./src/server/db\";
import { newId } from \"./src/lib/id\";
import { toIsoTimestamp } from \"./src/types/common\";
import type { OrgId, UserId } from \"./src/types/common\";
import type { Actor } from \"./src/types/member\";
import { registerEventHandlers, unregisterEventHandlers } from \"./src/server/services/event-registry\";
import { createApiToken, authenticateApiToken, listApiTokens, revokeApiToken } from \"./src/server/services/api-token-service\";
import { removeMember } from \"./src/server/services/member-service\";
import { eq } from \"drizzle-orm\";

process.env.TASKFLOW_DB_PATH = \"./.api-token-check.db\";
await runMigrations();
const db = getDb();
try {
  const orgId = newId() as OrgId;
  const owner: Actor = { orgId, userId: newId() as UserId, role: \"owner\" };
  const actor: Actor = { orgId, userId: newId() as UserId, role: \"member\" };
  const stamp = toIsoTimestamp(new Date());
  db.insert(organizations).values({ id: orgId, name: \"Check\", slug: \"check\", ownerId: owner.userId, createdAt: stamp, updatedAt: stamp }).run();
  for (const person of [owner, actor]) db.insert(members).values({ id: newId(), orgId, userId: person.userId, role: person.role, status: \"active\", createdAt: stamp, updatedAt: stamp }).run();
  registerEventHandlers();
  await assert.rejects(createApiToken(actor, { orgId, name: \" \", scope: \"read\", expiresInDays: 1 }));
  await assert.rejects(createApiToken({ ...actor, role: \"viewer\" }, { orgId, name: \"x\", scope: \"write\", expiresInDays: 1 }));
  assert.equal(db.select().from(apiTokens).all().length, 0);
  const read = await createApiToken(actor, { orgId, name: \" read \", scope: \"read\", expiresInDays: 1 });
  assert.equal(read.apiToken.name, \"read\");
  assert.match(read.token, /"'^tfk_['"\\w-]+"'$/);
  assert.equal(read.apiToken.prefix, read.token.slice(0, 12));
  assert.equal("tokenHash" in read.apiToken, false);
  assert.deepEqual(await authenticateApiToken(read.token), { ...actor, role: "viewer" });
  const write = await createApiToken(actor, { orgId, name: "write", scope: "write", expiresInDays: 1 });
  assert.deepEqual(await authenticateApiToken(write.token), actor);
  db.update(members).set({ role: "viewer" }).where(eq(members.userId, actor.userId)).run();
  assert.deepEqual(await authenticateApiToken(write.token), { ...actor, role: "viewer" });
  for (let i = 0; i < 3; i++) await createApiToken(actor, { orgId, name: "x", scope: "read", expiresInDays: 1 });
  await assert.rejects(createApiToken(actor, { orgId, name: "sixth", scope: "read", expiresInDays: 1 }));
  const revoked = await revokeApiToken(actor, orgId, read.apiToken.id);
  assert.deepEqual(await revokeApiToken(actor, orgId, read.apiToken.id), revoked);
  assert.equal(await authenticateApiToken(read.token), null);
  await createApiToken(actor, { orgId, name: "replacement", scope: "read", expiresInDays: 1 });
  const target = db.select().from(members).where(eq(members.userId, actor.userId)).get()!;
  await removeMember(owner, { orgId, memberId: target.id as import("./src/types/common").MemberId });
  const all = await listApiTokens(owner, orgId, actor.userId);
  assert.equal(all.length, 6);
  assert.ok(all.every(t => t.revokedAt !== null));
  assert.equal(await authenticateApiToken(write.token), null);
  const audit = db.select().from(activityEvents).all();
  assert.equal(audit.filter(a => a.action === "api_token.created").length, 6);
  assert.equal(audit.filter(a => a.action === "api_token.revoked").length, 6);
  assert.equal(audit.filter(a => a.action === "api_token.revoked" && a.actorId === owner.userId).length, 5);
  assert.ok(!JSON.stringify(audit).includes(write.token));
  console.log("API token integration checks passed");
} finally {
  unregisterEventHandlers();
  db.$client.close();
  for (const suffix of ["", "-wal", "-shm"]) rmSync(`.api-token-check.db${suffix}`, { force: true });
}
